App.data.ajouterTermes([
  { ar: "المُدَوَّنَة", translit: "al-moudawwana", def: "Recueil fondateur de l'école malikite : réponses d'Ibn al-Qāsim fondées sur l'enseignement de Mālik, recueillies par Asad ibn al-Furāt puis revues et ordonnées par Saḥnūn. Al-Ḥaṭṭāb la dit « base de l'école »." },
  { ar: "الأُمّ", translit: "al-oumm", def: "« La mère » : nom de la Mudawwana originale, par opposition à ses abrégés." },
  { ar: "التَّهْذِيب", translit: "at-tahdhîb", def: "Abrégé de la Mudawwana par Abū Saʿīd al-Barādhiʿī ; beaucoup l'appellent simplement « la Mudawwana »." },
  { ar: "تَأْوِيل", translit: "ta'wîl", def: "Interprétation. Au sens strict : faire sortir un mot de son sens apparent. Chez Khalīl : toute lecture du texte de la Mudawwana proposée par ses commentateurs." },
  { ar: "تَأْوِيلَانِ", translit: "ta'wîlâni", def: "« Deux interprétations » : deux façons dont les commentateurs ont compris un passage de la Mudawwana." },
  { ar: "تَأْوِيلَاتٌ", translit: "ta'wîlâtoun", def: "« Des interprétations » : plus de deux lectures d'un passage de la Mudawwana par ses commentateurs." },
  { ar: "مَادَّة", translit: "mâdda", def: "Racine : ensemble des mots formés sur les mêmes lettres de base." },
  { ar: "مَشْهُور", translit: "machhoûr", def: "L'avis le plus répandu dans l'école." },
  { ar: "رَاجِح", translit: "râjih", def: "L'avis le plus fort par ses preuves." },
  { ar: "تَغْلِيب", translit: "taghlîb", def: "Usage par extension : employer un même mot pour des cas voisins." },
  { ar: "اِخْتِيَار", translit: "ikhtiyâr", def: "Choix. Chez Khalīl, la racine de ce mot renvoie aux choix d'al-Lakhmī." },
  { ar: "المُخْتَار", translit: "al-moukhtâr", def: "Forme nominale : choix d'al-Lakhmī parmi des avis déjà transmis." },
  { ar: "اُخْتِيرَ", translit: "oukhtîra", def: "Forme verbale : avis qu'al-Lakhmī a formé lui-même." },
  { ar: "حُدُوث", translit: "houdoûth", def: "Le fait d'être nouveau ; sens exprimé par le verbe." },
  { ar: "ثُبُوت", translit: "thouboût", def: "Le fait d'être établi ; sens exprimé par le nom." },
  { ar: "تَرْجِيح", translit: "tarjîh", def: "Fait de faire pencher la balance vers un avis. Chez Khalīl, la racine de ce mot renvoie à Ibn Yūnus." },
  { ar: "الأَرْجَح", translit: "al-arjah", def: "Forme nominale : choix d'Ibn Yūnus parmi des avis déjà transmis." },
  { ar: "رُجِّحَ", translit: "roujjiha", def: "Forme verbale : avis qu'Ibn Yūnus a formé lui-même (usage rare)." },
  { ar: "ظُهُور", translit: "zouhoûr", def: "Le fait d'être apparent. Chez Khalīl, la racine de ce mot renvoie à Ibn Rushd." },
  { ar: "الأَظْهَر", translit: "al-azhar", def: "Forme nominale : choix d'Ibn Rushd parmi des avis déjà transmis." },
  { ar: "ظَهَرَ", translit: "zahara", def: "Forme verbale : avis qu'Ibn Rushd a formé lui-même (usage rare)." },
  { ar: "رِوَايَات", translit: "riwâyât", def: "Récits transmis ; ici, les paroles transmises dans l'école." },
  { ar: "قَوْل", translit: "qawl", def: "Parole, avis. Chez Khalīl, la racine de ce mot renvoie à al-Māzirī." },
  { ar: "القَوْل", translit: "al-qawl", def: "Forme nominale : choix d'al-Māzirī parmi des avis antérieurs (usage rare)." },
  { ar: "قَالَ", translit: "qâla", def: "Forme verbale de « قَوْل » : avis qu'al-Māzirī a formé lui-même (usage fréquent). Attention : sans sujet exprimé ni antécédent, un verbe comme « قَالَ » renvoie à Mālik (t. 1, p. 39)." },
  { ar: "مُجْتَهِد", translit: "moujtahid", def: "Juriste capable de dégager lui-même les règles à partir des sources." },
  { ar: "خِلَاف", translit: "khilâf", def: "Divergence. Chez Khalīl, en fin de question : des savants de même rang ont déclaré mashhūr des avis différents." },
  { ar: "تَشْهِير", translit: "tachhîr", def: "Fait de déclarer un avis « mashhūr »." },
  { ar: "الرَّاجِح", translit: "ar-râjih", def: "L'avis le plus fort par ses preuves." },
  { ar: "المُفْتَى بِهِ", translit: "al-mouftâ bihi", def: "L'avis sur lequel on rend les fatwas." },
  { ar: "قَوْلَانِ", translit: "qawlâni", def: "« Deux avis ». Chez Khalīl : deux avis dont aucun n'a été déclaré plus fort par écrit." },
  { ar: "أَقْوَال", translit: "aqwâl", def: "Avis (pluriel de « qawl »). Chez Khalīl : plusieurs avis dont aucun n'a été déclaré plus fort par écrit." },
  { ar: "أَرْجَحِيَّة", translit: "arjahiyya", def: "Supériorité d'un avis sur les autres." },
  { ar: "مَنْصُوصَة", translit: "mansoûsa", def: "Établie par écrit chez un savant, et non seulement perçue par Khalīl." },
  { ar: "مُسْتَفْتِي", translit: "moustaftî", def: "Celui qui demande un avis juridique (fatwa)." },
  { ar: "عَامِّيّ", translit: "ʿâmmî", def: "Personne qui n'est pas savante en droit." },
  { ar: "مَفْهُوم", translit: "mafhoûm", def: "Sens implicite : ce que la phrase indique sans le dire." },
  { ar: "مَنْطُوق", translit: "mantoûq", def: "Sens explicite : ce que la phrase dit expressément." },
  { ar: "مَفْهُومُ المُوَافَقَةِ", translit: "mafhoûmou l-mouwâfaqa", def: "Sens implicite de concordance : le cas non dit reçoit la même règle, parfois a fortiori." },
  { ar: "مَفْهُومُ المُخَالَفَةِ", translit: "mafhoûmou l-moukhâlafa", def: "Sens implicite contraire : le cas non dit reçoit la règle opposée." },
  { ar: "مَفْهُومُ الشَّرْطِ", translit: "mafhoûmou ch-chart", def: "Sens implicite de la condition : si la condition manque, la règle contraire s'applique. Le seul que Khalīl retienne d'office." },
  { ar: "غَايَة", translit: "ghâya", def: "Limite (« jusqu'à… ») ; son sens implicite est retenu par Khalīl selon al-Ḥaṭṭāb." },
  { ar: "حَصْر", translit: "hasr", def: "Restriction (« seulement… ») ; son sens implicite est retenu par Khalīl selon al-Ḥaṭṭāb." },
  { ar: "صُحِّحَ", translit: "souhhiha", def: "« A été jugé correct » : jugement d'un savant non nommé, autre que les quatre." },
  { ar: "اُسْتُحْسِنَ", translit: "oustouhsina", def: "« A été jugé bon » : jugement d'un savant non nommé, autre que les quatre." },
  { ar: "الأَصَحّ", translit: "al-asahh", def: "« Le plus correct » : forme adjectivale du jugement d'un savant non nommé." },
  { ar: "الأَحْسَن", translit: "al-ahsan", def: "« Le meilleur » : forme adjectivale du jugement d'un savant non nommé." },
  { ar: "تَصْحِيح", translit: "tashîh", def: "Selon Ibn Ghāzī : ce qu'un savant valide dans les paroles d'un autre." },
  { ar: "اِسْتِحْسَان", translit: "istihsân", def: "Selon Ibn Ghāzī, dans ce passage : ce qu'un savant juge bon lui-même." },
  { ar: "تَرَدُّد", translit: "taraddoud", def: "Hésitation, perplexité. Chez Khalīl : hésitation des savants tardifs, sur la transmission des anciens ou faute de texte des anciens." },
  { ar: "المُتَأَخِّرُون", translit: "al-mouta'akhkhiroûn", def: "Les savants tardifs de l'école." },
  { ar: "المُتَقَدِّمُون", translit: "al-moutaqaddimoûn", def: "Les anciens de l'école." },
  { ar: "طَرِيقَة", translit: "tarîqa", def: "« Voie » : un ou plusieurs maîtres qui présentent toute l'école selon ce qu'ils en ont transmis (définition de Khalīl dans at-Tawḍīḥ)." },
  { ar: "طُرُق", translit: "tourouq", def: "« Voies » : divergences entre maîtres sur la manière de transmettre l'école." },
  { ar: "لَوْ", translit: "law", def: "« Même si ». Chez Khalīl, en fin de règle : signale un avis contraire à l'intérieur de l'école malikite." },
  { ar: "خِلَافٌ مَذْهَبِيٌّ", translit: "khilâfoun madh-habiyyoun", def: "Divergence interne à l'école malikite." },
  { ar: "خِلَافٌ قَوْلِيٌّ", translit: "khilâfoun qawliyyoun", def: "Divergence entre des avis formulés (أَقْوَال)." },
  { ar: "تَكْمِيل", translit: "takmîl", def: "Complément : nom de la section où al-Ḥaṭṭāb ajoute des règles de lecture à celles de Khalīl." },
  { ar: "تَمْثِيل", translit: "tamthîl", def: "Fait de donner un exemple." },
  { ar: "نُكْتَة", translit: "noukta", def: "Raison fine, intention précise derrière une formulation." },
  { ar: "نَظَائِر", translit: "nazâ'ir", def: "Cas semblables, regroupés parce qu'ils partagent une règle." },
  { ar: "تَفْصِيل", translit: "tafsîl", def: "Distinction entre plusieurs situations qui n'ont pas la même règle." },
  { ar: "قَيْد", translit: "qayd", def: "Précision ou condition qui restreint une règle." },
  { ar: "كَافُ التَّشْبِيهِ", translit: "kâfou t-tachbîh", def: "La lettre « ka » (« comme ») ; chez Khalīl, elle marque les cas auxquels se limite une précision qui suit." },
  { ar: "غَالِبًا", translit: "ghâliban", def: "« Le plus souvent » : la règle admet des exceptions." },
  { ar: "ضَمِير", translit: "damîr", def: "Pronom ; ici, le pronom sujet sous-entendu d'un verbe." },
  { ar: "كَرِهَ", translit: "kariha", def: "« Il a jugé déconseillé » ; sans sujet exprimé chez Khalīl : Mālik." },
  { ar: "رَخَّصَ", translit: "rakhkhasa", def: "« Il a autorisé par exception » ; sans sujet exprimé chez Khalīl : Mālik." },
  { ar: "أَجَازَ", translit: "ajâza", def: "« Il a permis » ; sans sujet exprimé chez Khalīl : Mālik." },
  { ar: "نَدْب", translit: "nadb", def: "Recommandation. Chez Khalīl : le recommandé simple (istiḥbāb), distinct de la sunna." },
  { ar: "مَنْدُوب", translit: "mandoûb", def: "Recommandé. Chez Khalīl : synonyme de mustaḥabb." },
  { ar: "اِسْتِحْبَاب", translit: "istihbâb", def: "Fait d'être simplement recommandé." },
  { ar: "مُسْتَحَبّ", translit: "moustahabb", def: "Acte simplement recommandé ; chez Khalīl, deuxième rang du recommandé (selon al-Ḥaṭṭāb)." },
  { ar: "سُنَّة", translit: "sounna", def: "Rang le plus haut du recommandé, selon tous les auteurs cités par al-Ḥaṭṭāb." },
  { ar: "سُنَّةٌ مُؤَكَّدَة", translit: "sounna mou'akkada", def: "Sunna confirmée ; Khalīl distingue la sunna confirmée de celle qui ne l'est pas." },
  { ar: "فَضِيلَة", translit: "fadîla", def: "Mérite : nom d'un rang du recommandé (le deuxième chez Khalīl selon al-Ḥaṭṭāb, et chez al-Māzirī)." },
  { ar: "نَافِلَة", translit: "nâfila", def: "Œuvre surérogatoire ; chez Ibn Rushd et al-Māzirī, troisième rang du recommandé." },
  { ar: "رَغَائِب", translit: "raghâ'ib", def: "Chez Ibn Rushd : deuxième rang du recommandé (ce que le Prophète ﷺ a fait avec constance à la manière des œuvres surérogatoires, ou encouragé)." },
  { ar: "رَغِيبَة", translit: "raghîba", def: "Singulier de raghāʾib ; chez Ibn Bashīr, autre nom de la faḍīla." },
  { ar: "نَوَافِل", translit: "nawâfil", def: "Œuvres surérogatoires ; troisième rang du recommandé chez Ibn Rushd et al-Māzirī." },
  { ar: "فَضَائِل", translit: "fadâ'il", def: "Pluriel de faḍīla ; chez al-Māzirī, deuxième rang du recommandé." },
  { ar: "جَوَاز", translit: "jawâz", def: "Permission. Chez les malikites, en général : l'acte neutre (mubāḥ). Au sens large (al-Qarāfī) : toute possibilité d'agir, obligatoire compris." },
  { ar: "مُبَاح", translit: "moubâh", def: "Acte neutre : le faire ou s'en abstenir revient au même." },
  { ar: "فَرْض", translit: "fard", def: "Obligatoire ; synonyme de wājib dans l'école malikite." },
  { ar: "وَاجِب", translit: "wâjib", def: "Obligatoire : ce dont l'abandon est un péché ; parfois, ce dont dépend la validité d'un acte." },
  { ar: "مُتَرَادِفَان", translit: "moutarâdifân", def: "Deux mots synonymes." },
  { ar: "الرِّوَايَات", translit: "ar-riwâyât", def: "Le plus souvent, chez Khalīl et d'autres : les avis de Mālik." },
  { ar: "الأَقْوَال", translit: "al-aqwâl", def: "Le plus souvent, chez Khalīl et d'autres : les avis des compagnons de Mālik et des savants postérieurs." },
  { ar: "الاتِّفَاق", translit: "al-ittifâq", def: "L'accord des savants de l'école malikite." },
  { ar: "الإِجْمَاع", translit: "al-ijmâʿ", def: "Le consensus de l'ensemble des savants." },
  { ar: "الفُقَهَاءُ السَّبْعَةُ", translit: "al-fouqahâ'ou s-sabʿa", def: "« Les sept juristes » : Saʿīd ibn al-Musayyib, ʿUrwa, al-Qāsim ibn Muḥammad, Khārija, ʿUbayd Allāh, Sulaymān ibn Yasār, et un septième discuté." },
  { ar: "المَدَنِيُّونَ", translit: "al-madaniyyoûn", def: "« Les Médinois » : Ibn Kināna, Ibn al-Mājishūn, Muṭarrif, Ibn Nāfiʿ, Ibn Maslama et leurs pairs." },
  { ar: "المِصْرِيُّونَ", translit: "al-misriyyoûn", def: "« Les Égyptiens » : Ibn al-Qāsim, Ashhab, Ibn Wahb, Aṣbagh, Ibn ʿAbd al-Ḥakam et leurs pairs." },
  { ar: "العِرَاقِيُّونَ", translit: "al-ʿirâqiyyoûn", def: "« Les Irakiens » : le qāḍī Ismāʿīl, Ibn al-Qaṣṣār, Ibn al-Jallāb, le qāḍī ʿAbd al-Wahhāb, le qāḍī Abū l-Faraj, al-Abharī et leurs pairs." },
  { ar: "المَغَارِبَةُ", translit: "al-maghâriba", def: "« Les Maghrébins » : Ibn Abī Zayd, Ibn al-Qābisī, Ibn al-Labbād, al-Bājī, al-Lakhmī, Ibn Muḥriz, Ibn ʿAbd al-Barr, Ibn Rushd, Ibn al-ʿArabī, le qāḍī Sanad…" },
  { ar: "فَوَائِد", translit: "fawâ'id", def: "« Remarques utiles » : notes ajoutées par un auteur." },
  { ar: "الجُمْهُور", translit: "al-joumhoûr", def: "« La majorité » ; en droit comparé, selon un maître cité par Zarrūq : Mālik, ash-Shāfiʿī, Aḥmad et Abū Ḥanīfa." },
  { ar: "تَخْرِيج", translit: "takhrîj", def: "Déduction d'un avis à partir d'un autre avis ou d'une règle de l'école, sans texte transmis sur la question." },
  { ar: "يُخْتَلَفُ", translit: "youkhtalafou", def: "« On diverge » ; chez al-Lakhmī, l'avis opposé est souvent une déduction ou son propre choix." },
  { ar: "تَقْيِيد", translit: "taqyîd", def: "Notes prises par des élèves pendant l'enseignement d'un maître." },
  { ar: "تَقَايِيد", translit: "taqâyîd", def: "Pluriel de taqyīd : recueils de notes d'élèves." },
  { ar: "تَأْلِيف", translit: "ta'lîf", def: "Ouvrage composé par son auteur lui-même." },
  { ar: "يَنْبَغِي", translit: "yanbaghî", def: "« Il convient » ; en principe, mot de la recommandation (al-Jazūlī, Ibn Ghāzī)." },
  { ar: "لَا بَأْسَ", translit: "lâ ba'sa", def: "« Il n'y a pas de mal » ; selon Ibn Rushd, expression de la permission (ibāḥa)." },
  { ar: "إِبَاحَة", translit: "ibâha", def: "Permission : statut de l'acte neutre (mubāḥ)." },
  { ar: "مَكْرُوه", translit: "makroûh", def: "Déconseillé : ce dont l'abandon est récompensé et dont l'accomplissement n'est pas puni." },
  { ar: "كَرَاهَة", translit: "karâha", def: "Fait d'être déconseillé ; elle a des degrés selon la force de la demande." },
  { ar: "خِلَافُ الأَوْلَى", translit: "khilâfou l-awlâ", def: "« Contraire au mieux » : chez certains auteurs tardifs, délaissement d'un acte recommandé moins fortement demandé." },
  { ar: "مَرْجُوح", translit: "marjoûh", def: "Moins bon, qui pèse moins que son contraire." },
  { ar: "سَمَاع", translit: "samâʿ", def: "« Audition » : ensemble des réponses entendues par un disciple (de Mālik ou d'Ibn al-Qāsim), réunies dans al-ʿUtbiyya." },
  { ar: "أَسْمِعَة", translit: "asmiʿa", def: "Pluriel de samāʿ." },
  { ar: "رَسْم", translit: "rasm", def: "Cahier d'une audition, nommé d'après sa première question ; équivaut à un faṣl." },
  { ar: "تَرْجَمَة", translit: "tarjama", def: "Titre d'un cahier : sa première question." },
  { ar: "العُتْبِيَّة", translit: "al-ʿoutbiyya", def: "Recueil d'auditions réuni par al-ʿUtbī, commenté par Ibn Rushd dans al-Bayān." },
  { ar: "الحَدَث", translit: "al-hadath", def: "État d'impureté rituelle qui empêche de prier, levé par les ablutions ou le ghousl." },
  { ar: "الخَبَث", translit: "al-khabath", def: "Impureté matérielle (najāsa)." },
  { ar: "حُكْمُ الخَبَثِ", translit: "houkmou l-khabath", def: "Règle de l'impureté : le fait qu'une chose souillée reste interdite dans la prière et l'alimentation." },
  { ar: "المَاءُ المُطْلَق", translit: "al-mâ'ou l-moutlaq", def: "Eau absolue : ce qu'on peut appeler simplement « eau », sans qualificatif obligé." },
  { ar: "الطَّهَارَة", translit: "at-tahâra", def: "Purification ; dans la Loi, qualité juridique qui permet de prier, ou acte de lever le ḥadath et d'ôter l'impureté." },
  { ar: "النَّجَاسَة", translit: "an-najâsa", def: "Impureté ; qualité juridique qui interdit de prier avec une chose ou dans un lieu." },
  { ar: "اِسْتِجْمَار", translit: "istijmâr", def: "Se nettoyer après le besoin avec des pierres ou un matériau semblable." },
  { ar: "رُخْصَة", translit: "roukhsa", def: "Dispense accordée par la Loi en raison d'une difficulté." },
  { ar: "المَاءُ المُضَاف", translit: "al-mâ'ou l-moudâf", def: "Eau « mêlée » : eau changée par un mélange au point de perdre son caractère d'eau absolue." },
  { ar: "الطَّهُور", translit: "at-tahoûr", def: "Eau purifiante : pure et capable de purifier." },
  { ar: "زَمْزَم", translit: "zamzam", def: "Puits de La Mecque ; son eau est une eau absolue." },
  { ar: "آبَارُ ثَمُودَ", translit: "âbârou thamoûd", def: "Puits du pays du peuple de Thamūd (al-Ḥijr), dont l'eau ne doit pas être utilisée, sauf le puits de la chamelle." },
  { ar: "مَاءُ سَخَطٍ", translit: "mâ'ou sakhat", def: "« Eau de colère » : eau d'une terre frappée par le châtiment divin." },
  { ar: "النَّدَى", translit: "an-nadâ", def: "Rosée : humidité qui se dépose la nuit sur le sol et les feuilles." },
  { ar: "تَيَمُّم", translit: "tayammoum", def: "Ablution sèche, faite avec la terre pure quand l'eau manque ou ne peut être utilisée." },
  { ar: "الجُمُود", translit: "al-joumoûd", def: "Fait de geler ou de se solidifier ; contraire de « fondre »." },
  { ar: "الثَّلْج", translit: "ath-thalj", def: "Neige." },
  { ar: "البَرَد", translit: "al-barad", def: "Grêle." },
  { ar: "سُؤْر", translit: "sou'r", def: "Reste d'une boisson après qu'un être vivant en a bu." },
  { ar: "حَائِض", translit: "hâ'id", def: "Femme en période de règles." },
  { ar: "جُنُب", translit: "jounoub", def: "Personne en état de janâba, qui doit faire le ghousl." },
  { ar: "الجَلَّالَة", translit: "al-jallâla", def: "Animal qui se nourrit habituellement d'impuretés." },
  { ar: "الطُّهَارَة", translit: "at-touhâra", def: "Avec ḍamma : l'eau qui reste après la purification." },
  { ar: "فَضْلَة", translit: "fadla", def: "Reste, ce qui demeure après usage." },
  { ar: "المَاءُ الكَثِيرُ", translit: "al-mâ'ou l-kathîr", def: "Eau abondante ; selon al-Dardīr, plus que le récipient du ghousl." },
  { ar: "شَكّ", translit: "chakk", def: "Doute : les deux possibilités se valent." },
  { ar: "ظَنّ", translit: "zann", def: "Opinion probable : une possibilité l'emporte." },
  { ar: "الحَمْأَة", translit: "al-ham'a", def: "Vase noire et malodorante." },
  { ar: "مُجَاوِر", translit: "moujâwir", def: "Chose voisine de l'eau, qui ne s'y mêle pas." },
  { ar: "لَاصِق", translit: "lâsiq", def: "Qui touche (ici : la surface de l'eau) sans s'y mêler." },
  { ar: "مُمَازِج", translit: "moumâzij", def: "Qui se mêle intimement à l'eau." },
  { ar: "دُهْن", translit: "douhn", def: "Huile, graisse." },
  { ar: "قَطِرَان", translit: "qatirân", def: "Goudron végétal (genévrier, cèdre) dont on enduisait les outres." },
  { ar: "وِعَاء", translit: "wiʿâ'", def: "Récipient, outre." },
  { ar: "مُتَوَلِّد", translit: "moutawallid", def: "Ce qui naît de l'eau elle-même (mousse, algues, petits animaux aquatiques)." },
  { ar: "الطُّحْلُب", translit: "at-touhloub", def: "Mousse verte qui couvre l'eau stagnante." },
  { ar: "قَرَار", translit: "qarâr", def: "Lit de l'eau : la terre sur laquelle elle repose ou coule." },
  { ar: "سَبْخَة", translit: "sabkha", def: "Terre salée." },
  { ar: "مَطْرُوح", translit: "matroûh", def: "Ce qu'on a jeté dans l'eau." },
  { ar: "قَصْدًا", translit: "qasdan", def: "Exprès, volontairement." },
  { ar: "سَلْب", translit: "salb", def: "Ici : perte du pouvoir purifiant de l'eau." },
  { ar: "مَعْدِنِيّ", translit: "maʿdinî", def: "Extrait tel quel de la terre (ici : le sel de mine ou de saline)." },
  { ar: "مَصْنُوع", translit: "masnoûʿ", def: "Fabriqué. Pour le sel, selon al-Dardīr : tiré de terre salée chauffée au feu." },
  { ar: "طَاهِرٌ غَيْرُ مُطَهِّرٍ", translit: "tâhiroun ghayrou moutahhirin", def: "Pur mais non purifiant : eau qu'on peut boire et employer aux usages courants, mais qui ne lève ni le ḥadath ni la souillure." },
  { ar: "العَادَات", translit: "al-ʿâdât", def: "Les usages courants : boire, cuisiner, pétrir, laver la saleté." },
  { ar: "العِبَادَات", translit: "al-ʿibâdât", def: "Les actes d'adoration ; ici, les purifications rituelles." },
  { ar: "مُتَنَجِّس", translit: "moutanajjis", def: "Chose pure en soi devenue souillée par une impureté." },
  { ar: "مُصْطَكَى", translit: "moustakâ", def: "Mastic : résine odorante qu'on brûle pour parfumer l'eau ou les récipients." },
  { ar: "بُخَار", translit: "boukhâr", def: "Vapeur ; selon al-Dardīr, ici : la fumée (دُخَان)." },
  { ar: "سَانِيَة", translit: "sâniya", def: "Dispositif pour tirer l'eau d'un puits. Al-Ḥaṭṭāb : « la corde sur laquelle on puise » ; al-Dardīr : « سَاقِيَة » (roue à eau) ; Ibn Farḥūn en distingue deux sortes : celle qui tourne avec des godets et celle que des bêtes font aller et venir." },
  { ar: "بَيِّن", translit: "bayyin", def: "Net, apparent. Pour le changement de l'eau, selon al-Dasūqī : abondant et grossier." },
  { ar: "فَاحِش", translit: "fâhich", def: "Grossier, excessif (se dit d'un changement très marqué)." },
  { ar: "عُرْف", translit: "ʿourf", def: "L'usage reconnu des gens, qui sert à apprécier une notion que le texte ne mesure pas." },
  { ar: "غَدِير", translit: "ghadîr", def: "Mare : eau que le torrent laisse derrière lui." },
  { ar: "رَوْث", translit: "rawth", def: "Crottin, déjections solides des bêtes." },
  { ar: "مَاشِيَة", translit: "mâchiya", def: "Bétail. Selon al-Dasūqī, le mot n'est pas restrictif ici : chevaux, mulets et ânes sont pareils." },
  { ar: "تِبْن", translit: "tibn", def: "Paille." },
  { ar: "البَادِيَة", translit: "al-bâdiya", def: "Le désert, la campagne des nomades, par opposition à la ville (الحَاضِرَة)." },
  { ar: "نَوَازِل", translit: "nawâzil", def: "Recueil de fatwas sur des cas réels soumis à un savant (ici, celles d'Ibn Rushd)." },
  { ar: "شُذُوذ", translit: "choudhoûdh", def: "Singularité : avis isolé qui s'écarte des principes de l'école." },
  { ar: "نَظَر", translit: "nazar", def: "Chez Khalīl : question à examiner, sur laquelle un savant hésite (ici Ibn ʿAṭāʾ Allāh)." },
  { ar: "المُخَالِطُ المُوَافِقُ", translit: "al-moukhâlitou l-mouwâfiq", def: "Chose mêlée à l'eau qui a la même couleur, le même goût et la même odeur qu'elle." },
  { ar: "مُخَالِف", translit: "moukhâlif", def: "Différent : chose mêlée dont les qualités diffèrent de celles de l'eau." },
  { ar: "الزَّرْجُون", translit: "az-zarjoûn", def: "Selon al-Dasūqī, plante dont le jus pressé ressemble à l'eau en toutes ses qualités." },
  { ar: "تَحَيُّر", translit: "tahayyour", def: "Perplexité. Al-Dasūqī : le taraddoud d'un seul savant a ce sens." },
  { ar: "رِيق", translit: "rîq", def: "Salive." },
  { ar: "خِلَافٌ فِي حَالٍ", translit: "khilâfoun fî hâl", def: "Divergence de fait : chaque avis vise un état différent de la chose ; si l'un voyait l'état visé par l'autre, il dirait comme lui." },
  { ar: "خِلَافٌ لَفْظِيّ", translit: "khilâfoun lafziyy", def: "Divergence de mots : les avis ne s'opposent pas sur le fond." },
  { ar: "مَضْمَضَة", translit: "madmada", def: "Rinçage de la bouche." },
  { ar: "مُسْتَعْمَل", translit: "moustaʿmal", def: "Eau « utilisée » : celle qui a coulé sur les membres lors d'une purification et qu'on a recueillie." },
  { ar: "قَصْرِيَّة", translit: "qasriyya", def: "Baquet, grande bassine où l'on peut se laver." },
  { ar: "مُرَاعَاةُ الخِلَافِ", translit: "mourâʿâtou l-khilâf", def: "Prise en compte de la divergence : adoucir ou nuancer une règle pour tenir compte de l'avis contraire." },
  { ar: "الإِعَادَةُ أَبَدًا", translit: "al-iʿâdatou abadan", def: "Refaire la prière même après la fin de son temps." },
  { ar: "تَجْدِيد", translit: "tajdîd", def: "Renouvellement des ablutions alors qu'on est déjà en état de pureté." },
  { ar: "التَّبَرُّد", translit: "at-tabarroud", def: "Bain pris pour se rafraîchir." },
  { ar: "ذِمِّيَّة", translit: "dhimmiyya", def: "Femme non musulmane vivant sous la protection des musulmans ; ici, épouse d'un musulman." },
  { ar: "يَسِير", translit: "yasîr", def: "Peu (d'eau) : la contenance d'un récipient d'ablutions ou de ghousl, ou moins." },
  { ar: "جَرَّة", translit: "jarra", def: "Jarre, cruche." },
  { ar: "زِير", translit: "zîr", def: "Grande jarre à eau ; al-Ḥaṭṭāb glose ainsi le mot « الحُبّ »." },
  { ar: "قُلَّتَانِ", translit: "qoullatâni", def: "« Deux grandes jarres » : mesure du hadith invoqué par les Shafiʿites ; un avis l'évalue à cinq cents raṭl de Bagdad." },
  { ar: "المَاءُ الجَارِي", translit: "al-mâ'ou l-jârî", def: "Eau courante." },
  { ar: "الإِعَادَةُ فِي الوَقْتِ", translit: "al-iʿâdatou fî l-waqt", def: "Refaire la prière seulement tant que son temps n'est pas sorti." },
  { ar: "وَلَغَ", translit: "walagha", def: "Laper : plonger la langue dans un liquide et l'agiter (al-Dardīr)." },
  { ar: "سِبَاع", translit: "sibâʿ", def: "Fauves, bêtes de proie." },
  { ar: "رَاكِد", translit: "râkid", def: "Stagnant, qui ne coule pas." },
  { ar: "مُسْتَبْحِر", translit: "moustabhir", def: "Vaste étendue d'eau, comme un lac." },
  { ar: "تَعَبُّدِيّ", translit: "taʿabbudiyy", def: "D'ordre cultuel : se dit d'une règle qui s'applique sans dépendre d'une cause sensible (ici, même si le corps est propre)." },
  { ar: "مِيضَأَة", translit: "mîda'a", def: "Salle ou bassin d'ablutions." },
  { ar: "حَمَّام", translit: "hammâm", def: "Bain public." },
  { ar: "خَمْر", translit: "khamr", def: "Vin, boisson enivrante." },
  { ar: "نَبِيذ", translit: "nabîdh", def: "Boisson fermentée, autre que le vin de raisin ; al-Dasūqī préfère dire « enivrant » pour l'inclure." },
  { ar: "بَهِيمَة", translit: "bahîma", def: "Bête de troupeau." },
  { ar: "الطَّوَّافُونَ", translit: "at-tawwâfoûn", def: "« Ceux qui circulent » dans la maison : les serviteurs (an-Nawawī)." },
  { ar: "إِسْرَاف", translit: "isrâf", def: "Gaspillage." },
  { ar: "مُشَمَّس", translit: "mouchammas", def: "Eau chauffée au soleil." },
  { ar: "بَرَص", translit: "baras", def: "Lèpre blanche, maladie qui décolore la peau." },
  { ar: "الصُّفْر", translit: "as-soufr", def: "Cuivre jaune, laiton." },
  { ar: "مُنْطَبِع", translit: "mountabiʿ", def: "Métal qu'on étire au marteau, comme le cuivre, le fer et le plomb (al-Dasūqī)." },
  { ar: "زُهُومَة", translit: "zouhoûma", def: "Graisse, odeur grasse que le métal chauffé laisse dans l'eau." },
  { ar: "مَائِع", translit: "mâ'iʿ", def: "Liquide." },
  { ar: "جَامِد", translit: "jâmid", def: "Solide." },
  { ar: "سَرَيَان", translit: "sarayân", def: "Le fait de se répandre à l'intérieur d'une chose (ici, d'une nourriture solide)." },
  { ar: "نَزْح", translit: "nazh", def: "Puisage : retirer de l'eau d'un puits ou d'une citerne." },
  { ar: "ذُو نَفْسٍ سَائِلَةٍ", translit: "dhoû nafsin sâ'ila", def: "Animal dont le sang coule quand on l'égorge ou le blesse." },
  { ar: "بَرِّيّ", translit: "barriyy", def: "Terrestre." },
  { ar: "بَحْرِيّ", translit: "bahriyy", def: "Aquatique." },
  { ar: "صِهْرِيج", translit: "sihrîj", def: "Citerne." },
  { ar: "مَاجِل", translit: "mâjil", def: "Réservoir, citerne d'eau de pluie." },
  { ar: "رُطُوبَات", translit: "routoûbât", def: "Humeurs, liquides qui sortent du corps." },
  { ar: "مُكَاثَرَة", translit: "moukâthara", def: "Apport d'une eau qui domine en quantité." },
  { ar: "اِسْتِصْحَاب", translit: "istishâb", def: "Présomption de continuité : on garde le statut antérieur tant que rien n'établit le contraire." },
  { ar: "خَبَرُ الوَاحِدِ", translit: "khabarou l-wâhid", def: "Information transmise par une seule personne." },
  { ar: "عَدْلُ الرِّوَايَةِ", translit: "ʿadlou r-riwâya", def: "Digne de foi au sens de la transmission : musulman, pubère, sain d'esprit, non débauché, homme ou femme, libre ou esclave (al-Dasūqī)." },
  { ar: "فَاسِق", translit: "fâsiq", def: "Débauché : celui qui commet ouvertement de graves péchés ; sa parole n'est pas acceptée comme information." },
  { ar: "مُخْبِر", translit: "moukhbir", def: "Informateur : celui qui donne l'information." },
  { ar: "تَوَاتُر", translit: "tawâtour", def: "Transmission de masse : nombre d'informateurs tel qu'on ne peut pas les supposer d'accord pour mentir." },
  { ar: "مَذْهَب", translit: "madh-hab", def: "Doctrine, école juridique ; dans la règle de l'information, la manière de juger ce qui est impur." },
  { ar: "يُسْتَحْسَنُ", translit: "youstahsanou", def: "« Il est jugé bon » ; dans le matn « فَقَالَ يُسْتَحْسَنُ تَرْكُهُ », selon al-Dardīr : « il est recommandé » (يُسْتَحَبُّ)." },
  { ar: "وُرُود", translit: "wouroûd", def: "Arrivée d'une chose sur une autre ; ici, l'eau versée sur l'impureté, ou l'impureté qui tombe dans l'eau." },
  { ar: "غُسَالَة", translit: "ghousâla", def: "Eau de lavage : celle qui se sépare de la chose lavée." },
  { ar: "خَشَاش", translit: "khachâch", def: "Petites bêtes de la terre sans sang propre (insectes, vers…)." },
  { ar: "مَيْتَة", translit: "mayta", def: "Cadavre : animal mort sans abattage rituel valable." },
  { ar: "دَمٌ ذَاتِيٌّ", translit: "damoun dhâtiyyoun", def: "Sang propre à l'animal, par opposition au sang venu d'ailleurs (comme celui que la puce a sucé)." },
  { ar: "الوَزَغ", translit: "al-wazagh", def: "Le gecko ; animal qui a de la chair et du sang, non compté parmi les bêtes sans sang." },
  { ar: "طَافِي", translit: "tâfî", def: "Qui flotte à la surface de l'eau (poisson mort de lui-même)." },
  { ar: "كِتَابِيّ", translit: "kitâbiyy", def: "Homme des Écritures : juif ou chrétien." },
  { ar: "مَجُوسِيّ", translit: "majoûsiyy", def: "Mazdéen, adorateur du feu." },
  { ar: "الضِّفْدَع", translit: "ad-difdaʿ", def: "La grenouille." },
  { ar: "السُّلَحْفَاة", translit: "as-soulahfât", def: "La tortue ; ici, la tortue d'eau." },
  { ar: "السَّرَطَان", translit: "as-saratân", def: "Le crabe." },
  { ar: "تِمْسَاح", translit: "timsâh", def: "Crocodile." },
  { ar: "ذَكَاة", translit: "dhakâ", def: "Abattage rituel, qui rend l'animal licite et pur." },
  { ar: "ذَبْح", translit: "dhabh", def: "Égorgement : mode d'abattage par la gorge." },
  { ar: "نَحْر", translit: "nahr", def: "Saignée au haut de la poitrine (pour le chameau notamment)." },
  { ar: "عَقْر", translit: "ʿaqr", def: "Blessure mortelle infligée à l'animal qui s'abat ainsi (gibier, animal qu'on ne peut pas maîtriser)." },
  { ar: "جَنِين", translit: "janîn", def: "Petit encore dans le ventre de sa mère." },
  { ar: "مُحَرَّمُ الأَكْلِ", translit: "mouharramou l-akl", def: "Animal interdit à la consommation." },
  { ar: "مَكْرُوهُ الأَكْلِ", translit: "makroûhou l-akl", def: "Animal dont la consommation est déconseillée (comme les fauves)." },
  { ar: "تَبْعِيضُ الذَّكَاةِ", translit: "tabʿîdou dh-dhakâ", def: "Fait que l'abattage vaille pour une partie de l'animal (la peau) et non pour une autre (la chair)." },
  { ar: "مَشِيمَة", translit: "machîma", def: "Placenta : enveloppe du petit à la naissance ; appelée aussi salâ." },
  { ar: "سَلَى", translit: "salâ", def: "Autre nom du placenta (mashîma)." },
  { ar: "فَرْث", translit: "farth", def: "Contenu de l'estomac et des intestins de l'animal." },
  { ar: "صُوف", translit: "soûf", def: "Laine (du mouton)." },
  { ar: "وَبَر", translit: "wabar", def: "Poil fin du chameau, du lièvre et des animaux semblables." },
  { ar: "زَغَب", translit: "zaghab", def: "Duvet qui entoure le tuyau de la plume." },
  { ar: "شَعْر", translit: "chaʿr", def: "Poil, crin, cheveu : le mot le plus général, pour l'humain comme pour les animaux." },
  { ar: "قَصَبَةُ الرِّيشِ", translit: "qasabatou r-rîch", def: "Tuyau de la plume." },
  { ar: "جَزّ", translit: "jazz", def: "Coupe, tonte : ôter les poils ou la laine sans les arracher." },
  { ar: "نَتْف", translit: "natf", def: "Arrachage des poils avec leur racine." },
  { ar: "نُورَة", translit: "noûra", def: "Chaux employée pour épiler." },
  { ar: "مُذَكَّى", translit: "moudhakkâ", def: "Animal abattu rituellement." },
  { ar: "جَمَاد", translit: "jamâd", def: "Chose inerte : corps où la vie n'a pas résidé et qui ne vient pas d'un être vivant." },
  { ar: "جِسْم", translit: "jism", def: "Corps : ce qui occupe un espace (genre de la définition)." },
  { ar: "سَمْن", translit: "samn", def: "Beurre clarifié." },
  { ar: "مُسْكِر", translit: "mouskir", def: "Ce qui enivre : fait perdre l'esprit sans les sens, avec exaltation et joie. Il est impur et entraîne la peine légale." },
  { ar: "مُفْسِد", translit: "moufsid", def: "Ce qui corrompt l'esprit : fait perdre l'esprit sans les sens, sans exaltation ni joie. Appelé aussi moukhaddir ; il est pur." },
  { ar: "مُخَدِّر", translit: "moukhaddir", def: "Stupéfiant : autre nom du moufsid chez al-Dardīr." },
  { ar: "مُرْقِد", translit: "mourqid", def: "Ce qui endort : fait perdre l'esprit et les sens. Il est pur." },
  { ar: "حَدّ", translit: "hadd", def: "Peine légale fixée par la Loi." },
  { ar: "تَعْزِير", translit: "taʿzîr", def: "Sanction dissuasive laissée à l'appréciation du juge, distincte de la peine légale." },
  { ar: "حَشِيشَة", translit: "hachîcha", def: "Le chanvre ; al-Qarāfī le range parmi ce qui corrompt, al-Manūfī parmi ce qui enivre." },
  { ar: "قَهْوَة", translit: "qahwa", def: "Le café, boisson tirée de l'écorce du café (qishr al-bunn), selon al-Ḥaṭṭāb." },
  { ar: "حَيّ", translit: "hayy", def: "Être vivant ; tout vivant est pur selon ce passage." },
  { ar: "عَذِرَة", translit: "ʿadhira", def: "Excréments, immondices." },
  { ar: "دَمْع", translit: "damʿ", def: "Larmes : ce qui coule de l'œil." },
  { ar: "عَرَق", translit: "ʿaraq", def: "Sueur : ce qui suinte du corps." },
  { ar: "سَكْرَان", translit: "sakrân", def: "Personne ivre." },
  { ar: "لُعَاب", translit: "louʿâb", def: "Salive : ce qui coule de la bouche." },
  { ar: "مُخَاط", translit: "moukhât", def: "Mucus : ce qui coule du nez." },
  { ar: "بَيْض", translit: "bayd", def: "Œufs." },
  { ar: "مَعِدَة", translit: "maʿida", def: "Estomac." },
  { ar: "حَشَرَات", translit: "hacharât", def: "Petites bêtes (insectes, reptiles comme le serpent)." },
  { ar: "مَذِر", translit: "madhir", def: "Œuf gâté : pourri, ou devenu sang, chair ou poussin mort. Il est impur." },
  { ar: "سَفْح", translit: "safh", def: "Le fait que le sang soit répandu ; seul le sang répandu est impur." },
  { ar: "فَضَلَات", translit: "fadalât", def: "Produits du corps : larmes, sueur, salive, mucus, etc." },
  { ar: "لَبَن", translit: "laban", def: "Lait." },
  { ar: "آدَمِيّ", translit: "âdamî", def: "Être humain." },
  { ar: "اِسْتِحَالَة", translit: "istihâla", def: "Transformation d'une chose en une autre ; le lait se transforme en une chose bonne, d'où sa pureté selon al-Dardīr." },
  { ar: "تَابِع", translit: "tâbiʿ", def: "Qui suit : le lait d'un animal suit la règle de sa chair." },
  { ar: "بَوْل", translit: "bawl", def: "Urine. Celle de l'animal licite à la consommation est pure." },
  { ar: "المُتَغَذِّي بِالنَّجَسِ", translit: "al-moutaghadhdhî bi-n-najas", def: "Animal licite qui se nourrit d'impuretés, en mangeant ou en buvant ; ses déjections sont impures." },
  { ar: "ذَرْق", translit: "dharq", def: "Fiente d'oiseau." },
  { ar: "قَيْء", translit: "qay'", def: "Vomissure ; selon al-Dardīr, la nourriture qui ressort après s'être fixée dans l'estomac." },
  { ar: "قَلْس", translit: "qals", def: "Remontée : eau que l'estomac rejette, ou qu'un vent pousse de l'entrée de l'estomac, parfois avec de la nourriture (Sanad, al-Dasūqī)." },
  { ar: "حُمُوضَة", translit: "houmoûda", def: "Acidité." },
  { ar: "صَفْرَاء", translit: "safrâ'", def: "Bile jaune : eau jaune et liée, semblable à une teinture de safran, qui sort de l'estomac (al-Dardīr)." },
  { ar: "بَلْغَم", translit: "balgham", def: "Phlegme, glaires : ce qui est coagulé comme le mucus et sort de la poitrine ou tombe de la tête (al-Dardīr)." },
  { ar: "سَوْدَاء", translit: "sawdâ'", def: "Bile noire ; impure selon al-Qarāfī (rapporté par Ibn ʿAbd as-Salām)." },
  { ar: "نُخَامَة", translit: "noukhâma", def: "Crachat, glaire ; al-Dasūqī : le phlegme est connu sous ce nom." },
  { ar: "مَرَارَة", translit: "marâra", def: "Fiel : selon al-Dardīr, le liquide jaune contenu dans la vésicule de l'animal égorgé (pluriel : مَرَائِر)." },
  { ar: "مَسْفُوح", translit: "masfoûh", def: "Sang répandu : celui qui coule à l'égorgement ou pendant la vie ; il est impur." },
  { ar: "عُرُوق", translit: "ʿouroûq", def: "Veines ; le sang qui y reste après l'égorgement est du sang non répandu, pur." },
  { ar: "مِسْك", translit: "misk", def: "Musc : parfum ; selon al-Dardīr, un sang coagulé transformé en chose bonne, donc pur." },
  { ar: "فَأْرَةُ المِسْكِ", translit: "fa'ratou l-misk", def: "Poche du musc : la petite peau qui le contient ; appelée aussi nâfiha." },
  { ar: "نَافِحَة", translit: "nâfiha", def: "Autre nom de la poche du musc (al-Ḥaṭṭāb)." },
  { ar: "زَرْع", translit: "zarʿ", def: "Culture : plante semée (céréales et autres)." },
  { ar: "بَقْل", translit: "baql", def: "Légumes verts, herbes potagères (comme le poireau)." },
  { ar: "الطِّرْطَار", translit: "at-tirtâr", def: "Dépôt dur que laisse le vin (tartre), employé par les teinturiers ; al-Dasūqī écrit « الطِّرْطِير »." },
  { ar: "الإِسْكَار", translit: "al-iskâr", def: "Pouvoir d'enivrer ; cause de l'impureté du vin." },
  { ar: "تَخْلِيل", translit: "takhlîl", def: "Transformer le vin en vinaigre, par exemple en y jetant du sel ou du vinaigre." },
  { ar: "خَلّ", translit: "khall", def: "Vinaigre." },
  { ar: "دَنّ", translit: "dann", def: "Grande jarre à vin." },
  { ar: "الِاسْتِثْنَاء", translit: "al-istithnâ'", def: "Exception : ce qui est exclu d'une règle générale, par « sauf » (إِلَّا) ou, au sens large, par une condition." },
  { ar: "النَّجَس", translit: "an-najas", def: "Avec fatḥa : la substance impure elle-même (urine, sang répandu…), par opposition à la chose souillée (النَّجِس, مُتَنَجِّس)." },
  { ar: "حَتْفَ أَنْفِهِ", translit: "hatfa anfihi", def: "Mort de lui-même, de mort naturelle." },
  { ar: "مُحْرِم", translit: "mouhrim", def: "Pèlerin en état de sacralisation (iḥrām)." },
  { ar: "قَمْلَة", translit: "qamla", def: "Pou." },
  { ar: "بُرْغُوث", translit: "bourghoûth", def: "Puce." },
  { ar: "قُرَاد", translit: "qourâd", def: "Tique." },
  { ar: "دَمٌ مَنْقُول", translit: "damoun manqoûl", def: "Sang « transporté » : sang que l'insecte prend à d'autres et qui ne lui est pas propre." },
  { ar: "الصِّئْبَان", translit: "as-si'bân", def: "Lentes : œufs du pou." },
  { ar: "الِاعْتِكَاف", translit: "al-iʿtikâf", def: "Retraite pieuse : séjour à la mosquée consacré à l'adoration." },
  { ar: "أُبِينَ", translit: "oubîna", def: "« A été détaché » : séparé du corps, réellement ou en restant suspendu sans pouvoir reprendre sa forme (al-Dardīr)." },
  { ar: "قَرْن", translit: "qarn", def: "Corne." },
  { ar: "عَظْم", translit: "ʿazm", def: "Os." },
  { ar: "ظِلْف", translit: "zilf", def: "Sabot fendu : celui de la vache, du mouton et de la gazelle ; pour al-Dardīr, il comprend aussi le sabot du cheval et de l'âne." },
  { ar: "ظُفْر", translit: "zoufr", def: "Ongle, griffe : celui de l'humain, du chameau, de l'oie, de la poule, de l'autruche." },
  { ar: "عَاج", translit: "ʿâj", def: "Ivoire : l'os, la défense de l'éléphant." },
  { ar: "رِيش", translit: "rîch", def: "Plume, plumes." },
  { ar: "سِنْخ", translit: "sinkh", def: "Racine, base (d'une plume, d'une dent)." },
  { ar: "جِلْد", translit: "jild", def: "Peau." },
  { ar: "دَبْغ", translit: "dabgh", def: "Tannage : traitement de la peau qui en ôte l'odeur et l'humidité et la préserve de la décomposition (al-Dardīr) ; on dit aussi dibâgh." },
  { ar: "الطَّهَارَةُ اللُّغَوِيَّة", translit: "at-tahâratou l-loughawiyya", def: "Pureté au sens de la langue : la propreté, distincte de la pureté légale (al-Dardīr)." },
  { ar: "طَهَارَةٌ مُقَيَّدَة", translit: "tahâra mouqayyada", def: "Pureté restreinte : pureté qui ne permet qu'un usage limité (ici, pour les choses sèches et l'eau)." },
  { ar: "خِنْزِير", translit: "khinzîr", def: "Porc." },
  { ar: "إِهَاب", translit: "ihâb", def: "Peau ; les lexicographes divergent : peau des bestiaux seulement, ou de tout animal." },
  { ar: "دِبَاغ", translit: "dibâgh", def: "Tannage (autre forme de dabgh)." },
  { ar: "قَرَظ", translit: "qaraz", def: "Feuilles d'acacia employées pour tanner." },
  { ar: "تَشْمِيس", translit: "tachmîs", def: "Exposition au soleil ; ne suffit pas pour tanner (Ibn Nāfiʿ)." },
  { ar: "يَابِس", translit: "yâbis", def: "Chose sèche (grains, etc.), par opposition aux liquides." },
  { ar: "سِقَاء", translit: "siqâ'", def: "Outre : récipient en peau pour l'eau ou le lait." },
  { ar: "فِرَاء", translit: "firâ'", def: "Fourrures (pluriel de farw)." },
  { ar: "سِنْجَاب", translit: "sinjâb", def: "Écureuil (petit-gris), dont la peau sert aux fourrures." },
  { ar: "أَنْيَابُ الفِيلِ", translit: "anyâbou l-fîl", def: "Défenses d'éléphant, d'où l'on tire l'ivoire." },
  { ar: "كَرَاهَةُ التَّنْزِيهِ", translit: "karâhatou t-tanzîh", def: "« Déconseillé » au sens propre : l'acte est blâmable sans être interdit, par opposition au « déconseillé » qui vaut interdiction." },
  { ar: "اِسْتِشْكَال", translit: "istichkâl", def: "Fait de signaler une difficulté ; Khalīl cite parfois la Mudawwana pour cela." },
  { ar: "اِسْتِشْهَاد", translit: "istich-hâd", def: "Fait de citer un texte à l'appui d'une règle." },
  { ar: "كَيْمَخْت", translit: "kaymakht", def: "Cuir tanné de la peau d'âne, de cheval ou de mulet morts (al-Dardīr, al-Dasūqī) ; mot persan arabisé." },
  { ar: "تَوَقُّف", translit: "tawaqqouf", def: "Abstention : un savant ne se prononce pas sur une question." },
  { ar: "تَعَمُّق", translit: "taʿammouq", def: "Sévérité excessive, rigorisme dans la pratique religieuse." },
  { ar: "جَفِير", translit: "jafîr", def: "Fourreau, gaine d'épée." },
  { ar: "مَنِيّ", translit: "maniyy", def: "Sperme (défini au chapitre du ghousl)." },
  { ar: "مَذْي", translit: "madhy", def: "Liquide fin qui sort quand le désir s'éveille, chez l'homme et la femme." },
  { ar: "وَدْي", translit: "wady", def: "Liquide blanc et épais qui sort après l'urine ou après un effort (porter une charge lourde)." },
  { ar: "تَشْرِيع", translit: "tachrîʿ", def: "Acte accompli pour enseigner une règle à la communauté." },
  { ar: "قَيْح", translit: "qayh", def: "Pus : humeur purulente que ne mêle aucun sang." },
  { ar: "صَدِيد", translit: "sadîd", def: "Sanie : eau fine de la plaie, mêlée de sang, avant que le pus ne s'épaississe." },
  { ar: "مِدَّة", translit: "midda", def: "Humeur purulente, pus." },
  { ar: "بَثَرَات", translit: "batharât", def: "Boutons, pustules de la peau." },
  { ar: "رُطُوبَةُ الفَرْجِ", translit: "routoûbatou l-farj", def: "Humidité du sexe ; impure chez l'humain et l'animal non licite, pure chez l'animal licite (al-Dardīr)." },
  { ar: "السَّبِيلَانِ", translit: "as-sabîlâni", def: "Les deux voies naturelles : l'avant et l'arrière." },
  { ar: "الهَادِي", translit: "al-hâdî", def: "Liquide qui sort du sexe de la femme avant l'accouchement." },
  { ar: "فَصْد", translit: "fasd", def: "Saignée : incision d'une veine pour en faire couler le sang." },
  { ar: "سَمَك", translit: "samak", def: "Poisson." },
  { ar: "تُرْسُ المَاءِ", translit: "tourcou l-mâ'", def: "Tortue d'eau ; Mālik la compte comme gibier de la mer." },
  { ar: "ذُبَاب", translit: "dhoubâb", def: "Mouche ; mot singulier selon Ibn Sīdah, singulier ذُبَابَة selon al-Ṣiḥāḥ." },
  { ar: "حَلَم", translit: "halam", def: "Petite tique." },
  { ar: "الأَخْلَاطُ الأَرْبَعَة", translit: "al-akhlâtou l-arbaʿa", def: "Les quatre humeurs du corps selon les anciens : la bile jaune, le sang, la bile noire et le phlegme." },
  { ar: "عَبِيط", translit: "ʿabît", def: "Pur, sans mélange (se dit du sang)." },
  { ar: "رَمَاد", translit: "ramâd", def: "Cendre." },
  { ar: "دُخَان", translit: "doukhân", def: "Fumée." },
  { ar: "اِنْعِكَاس", translit: "inʿikâs", def: "Retour de la fumée sur ce qu'on cuit ou chauffe." },
  { ar: "مُرْتَك", translit: "mourtak", def: "Onguent, pommade (ici fait d'os de cadavre brûlés)." },
  { ar: "عَرَقُ الحَمَّامِ", translit: "ʿaraqou l-hammâm", def: "Condensation qui coule des murs et du plafond du bain public." },
  { ar: "وَطْوَاط", translit: "watwât", def: "Chauve-souris." },
  { ar: "فَأْرَة", translit: "fa'ra", def: "Souris." },
  { ar: "حِمَارُ الوَحْشِ", translit: "himârou l-wahch", def: "Âne sauvage, onagre." },
  { ar: "وَدَك", translit: "wadak", def: "Graisse fondue." },
  { ar: "تَحَلُّل", translit: "tahalloul", def: "Fait qu'une chose se dissolve ou qu'il s'en détache des parcelles dans un liquide." },
  { ar: "زِقّ", translit: "ziqq", def: "Outre de peau (pluriel زِقَاق)." },
  { ar: "اِسْتِصْبَاح", translit: "istisbâh", def: "Fait de s'éclairer avec une lampe à huile." },
  { ar: "هَرْي", translit: "hary", def: "Tas, provision entassée (ici d'olives)." },
  { ar: "مَطْمُورَة", translit: "matmoûra", def: "Fosse ou silo souterrain où l'on garde le grain." },
  { ar: "دِرَاس", translit: "dirâs", def: "Foulage, battage du grain sur l'aire." },
  { ar: "مَرَق", translit: "maraq", def: "Bouillon, sauce de cuisson." },
  { ar: "تَشْوِيط", translit: "tachwît", def: "Flamber une tête ou des pattes pour en brûler les poils." },
  { ar: "سَمْط", translit: "samt", def: "Ébouillanter une volaille ou une bête pour la plumer ou l'épiler." },
  { ar: "نُضْج", translit: "noudj", def: "Cuisson complète, fait d'être cuit à point." },
  { ar: "تَمْلِيح", translit: "tamlîh", def: "Salage, mise au sel ou en saumure." },
  { ar: "صَلْق", translit: "salq", def: "Faire bouillir dans l'eau (des œufs, une volaille)." },
  { ar: "فَخَّار", translit: "fakhkhâr", def: "Poterie, terre cuite." },
  { ar: "غَوَّاص", translit: "ghawwâs", def: "Qui pénètre profondément : impureté qui s'infiltre dans la matière d'un récipient (vin, urine, eau impure)." },
  { ar: "مَطْلِيّ", translit: "matliyy", def: "Enduit, émaillé, vernissé." },
  { ar: "غُصَّة", translit: "ghoussa", def: "Obstruction de la gorge par une bouchée qui ne passe pas." },
  { ar: "مُضْطَرّ", translit: "moudtarr", def: "Personne contrainte par la nécessité (faim extrême), à qui le cadavre devient permis." },
  { ar: "تَدَاوٍ", translit: "tadâwin", def: "Fait de se soigner, de prendre un remède." },
  { ar: "أَتَان", translit: "atân", def: "Ânesse." },
  { ar: "حَرْبِيّ", translit: "harbiyy", def: "Non-musulman d'un territoire en guerre avec les musulmans, non lié par un pacte de protection." },
  { ar: "نَسْج", translit: "nasj", def: "Tissage ; ce qui a été tissé." },
  { ar: "كُوشَة", translit: "koûcha", def: "Four de boulanger (terme maghrébin)." },
  { ar: "عِمَامَة", translit: "ʿimâma", def: "Turban." },
  { ar: "قَلَنْسُوَة", translit: "qalansouwa", def: "Calotte, bonnet porté sur la tête ou sous le turban." },
  { ar: "نَضْح", translit: "nadh", def: "Aspersion d'eau sur ce dont on doute de la pureté." },
  { ar: "كَنَّاف", translit: "kannâf", def: "Vidangeur, celui qui nettoie les latrines." },
  { ar: "اِسْتِبْرَاء", translit: "istibrâ'", def: "Purification après la miction : faire sortir les dernières gouttes d'urine avant de se nettoyer." },
  { ar: "حَائِل", translit: "hâ'il", def: "Écran, ce qui s'interpose entre deux choses." },
  { ar: "سَرَاوِيل", translit: "sarâwîl", def: "Pantalon large porté à même le corps." },
  { ar: "مِئْزَر", translit: "mi'zar", def: "Pagne noué à la taille." },
  { ar: "مُحَلًّى", translit: "mouhallâ", def: "Orné d'or ou d'argent (par tissage, broderie, boutons, plaques)." },
  { ar: "مِنْطَقَة", translit: "mintaqa", def: "Ceinture que l'on serre à la taille." },
  { ar: "مُصْحَف", translit: "mous-haf", def: "Exemplaire écrit du Coran." },
  { ar: "إِجَازَة", translit: "ijâza", def: "Certificat par lequel un maître autorise un élève à transmettre ce qu'il lui a enseigné." },
  { ar: "شَرِيط", translit: "charît", def: "Fil, lien (ici, fil de métal qui attache une dent)." },
  { ar: "فَصّ", translit: "fass", def: "Chaton d'une bague (pierre ou plaque qui porte la gravure)." },
  { ar: "نَقْد", translit: "naqd", def: "Or et argent (métaux monnayés) ; « les deux naqd » : l'or et l'argent." },
  { ar: "اِقْتِنَاء", translit: "iqtinâ'", def: "Fait de posséder et de garder un objet chez soi, sans forcément s'en servir." },
  { ar: "ذَرِيعَة", translit: "dharîʿa", def: "Moyen qui conduit à un acte interdit ; on « ferme les moyens » (سَدُّ الذَّرَائِعِ)." },
  { ar: "تَجَمُّل", translit: "tajammoul", def: "Fait d'embellir, de décorer (ici, garder un objet pour l'apparat)." },
  { ar: "مُغَشًّى", translit: "mougachchâ", def: "Récipient d'or ou d'argent recouvert d'un autre métal." },
  { ar: "مُمَوَّه", translit: "moumawwah", def: "Récipient d'un autre métal plaqué ou enduit d'or ou d'argent." },
  { ar: "مُضَبَّب", translit: "moudabbab", def: "Récipient cassé, réparé avec des fils ou une plaque de métal (ici d'or ou d'argent)." },
  { ar: "سَرَف", translit: "saraf", def: "Gaspillage, dépense excessive." },
  { ar: "جَوْهَر", translit: "jawhar", def: "Pierre précieuse (perle, rubis, émeraude…)." },
  { ar: "بِلَّوْر", translit: "billawr", def: "Cristal de roche." },
  { ar: "حَرِير", translit: "harîr", def: "Soie." },
  { ar: "مُكْحُلَة", translit: "moukhoula", def: "Pot à khôl." },
  { ar: "قَبْقَاب", translit: "qabqâb", def: "Sabot, chaussure à semelle de bois." },
  { ar: "سَرِير", translit: "sarîr", def: "Lit (cadre de lit, couche surélevée)." },
  { ar: "مِرْوَد", translit: "mirwad", def: "Bâtonnet pour appliquer le khôl." },
  { ar: "مِذَبَّة", translit: "midhabba", def: "Chasse-mouches." },
  { ar: "مِقْرَمَة", translit: "miqrama", def: "Rideau ou tenture à motifs et dessins." },
  { ar: "تَزْوِيق", translit: "tazwîq", def: "Décoration, enjolivement (des murs, d'une mosquée)." },
  { ar: "إِزَالَةُ النَّجَاسَةِ", translit: "izâlatou n-najâsa", def: "Fait d'ôter l'impureté du vêtement, du corps ou du lieu ; on l'appelle aussi purification de la souillure (طَهَارَةُ الخَبَثِ)." },
  { ar: "خِلَافٌ مَعْنَوِيّ", translit: "khilâfoun maʿnawiyy", def: "Divergence de fond : les avis ne mènent pas aux mêmes conséquences ; contraire de la divergence de mots." },
  { ar: "عَامِد", translit: "ʿâmid", def: "Qui agit exprès, en connaissance de cause." },
  { ar: "عَاجِز", translit: "ʿâjiz", def: "Incapable ; ici, qui ne trouve ni eau pour laver l'impureté, ni vêtement pur, ni endroit pur." },
  { ar: "تَأْثِيم", translit: "ta'thîm", def: "Fait de juger quelqu'un pécheur." },
  { ar: "مَحْمُول", translit: "mahmoûl", def: "Ce que porte le fidèle : vêtements, chaussures, arme, sac, etc." },
  { ar: "تَضَمُّخ", translit: "tadammoukh", def: "Fait de se souiller, de s'enduire d'impureté ; hors de la prière, c'est déconseillé selon l'avis retenu." },
  { ar: "حَامِل", translit: "hâmil", def: "Qui porte ; le fidèle est réputé porter ce qui tient à lui et se déplace avec lui." },
  { ar: "خِبَاء", translit: "khibâ'", def: "Tente (de poil ou de tissu)." },
  { ar: "اِسْتِنَاد", translit: "istinâd", def: "Fait de s'adosser, de s'appuyer sur quelqu'un ou quelque chose." },
  { ar: "صِمَاخ", translit: "simâkh", def: "Conduit de l'oreille." },
  { ar: "تَقَايُؤ", translit: "taqâyou'", def: "Fait de se faire vomir." },
  { ar: "مِرْحَاض", translit: "mirhâd", def: "Latrines, lieu d'aisance." },
  { ar: "مُومِي", translit: "moûmî", def: "Celui qui prie par gestes de la tête, sans poser le front au sol (le malade, par exemple)." },
  { ar: "حَصِير", translit: "hasîr", def: "Natte, tapis de prière tressé ; par extension, tout ce qu'on étend pour prier dessus." },
  { ar: "قَارِب", translit: "qârib", def: "Barque." },
  { ar: "الظُّهْرَانِ", translit: "az-zouhrâni", def: "« Les deux ẓuhr » : le ẓuhr et le ʿaṣr, nommés ensemble par extension (taghlîb)." },
  { ar: "اِصْفِرَار", translit: "isfirâr", def: "Jaunissement du soleil, en fin d'après-midi." },
  { ar: "الوَقْتُ الضَّرُورِيّ", translit: "al-waqtou d-daroûriyy", def: "Temps de nécessité : fin du temps d'une prière, réservé à ceux qui ont une excuse." },
  { ar: "الوَقْتُ المُخْتَار", translit: "al-waqtou l-moukhtâr", def: "Temps choisi : temps normal d'une prière." },
  { ar: "إِسْفَار", translit: "isfâr", def: "Clarté de l'aube, quand le jour commence à paraître." },
  { ar: "فَائِتَة", translit: "fâ'ita", def: "Prière manquée, rattrapée après son temps." },
  { ar: "مُبْطِل", translit: "moubtil", def: "Ce qui annule (un acte d'adoration)." },
  { ar: "قَطْع", translit: "qatʿ", def: "Interruption de la prière commencée." },
  { ar: "بِنَاء", translit: "binâ'", def: "Fait de reprendre la prière là où on l'a laissée, sans la recommencer." },
  { ar: "مَأْمُوم", translit: "ma'moûm", def: "Celui qui prie derrière un imam." },
  { ar: "اِسْتِخْلَاف", translit: "istikhlâf", def: "Fait, pour l'imam qui doit quitter la prière, de désigner un fidèle pour la poursuivre à sa place." },
  { ar: "إِقَامَة", translit: "iqâma", def: "Second appel, dit juste avant de commencer la prière obligatoire." },
  { ar: "تَمَادِي", translit: "tamâdî", def: "Fait de poursuivre la prière commencée sans l'interrompre." },
  { ar: "رُعَاف", translit: "ruʿâf", def: "Saignement de nez ; chapitre où sont réglés les cas de sang qui coule pendant la prière." },
  { ar: "نَعْل", translit: "naʿl", def: "Sandale." },
  { ar: "بِدْعَة", translit: "bidʿa", def: "Innovation : pratique introduite dans la religion sans fondement dans la sunna." },
  { ar: "عَفْو", translit: "ʿafw", def: "Tolérance : l'impureté reste impure, mais on n'est pas tenu de l'ôter pour prier." },
  { ar: "مَعْفُوَّات", translit: "maʿfouwwât", def: "Les impuretés tolérées." },
  { ar: "مَشَقَّة", translit: "machaqqa", def: "Difficulté, peine ; selon son degré, elle fait tomber ou non une obligation." },
  { ar: "مُسْتَنْكِح", translit: "moustankih", def: "Chronique : ce qui revient sans cesse et domine la personne (au moins une fois par jour)." },
  { ar: "سَلَس", translit: "salas", def: "Incontinence : écoulement d'urine, de madhy ou d'autre chose qu'on ne peut retenir." },
  { ar: "اِسْتِحَاضَة", translit: "istihâda", def: "Saignement de la femme hors de ses règles, dû à un trouble." },
  { ar: "دُمَّل", translit: "doummal", def: "Furoncle." },
  { ar: "خِرْقَة", translit: "khirqa", def: "Linge, chiffon (ici, pour se protéger d'un écoulement)." },
  { ar: "بَاسُور", translit: "bâsoûr", def: "Hémorroïde : enflure de l'anus par l'intérieur, qui peut sortir et suinter (pluriel : بَوَاسِير)." },
  { ar: "نَاسُور", translit: "nâsoûr", def: "Plaie qui suinte ; selon az-Zubaydī, ouverture des veines de l'anus et écoulement de leur matière." },
  { ar: "ثَآلِيل", translit: "tha'âlîl", def: "Verrues, excroissances (singulier ثُؤْلُول)." },
  { ar: "الرَّدّ", translit: "ar-radd", def: "Ici : le fait de remettre en place, avec la main, l'hémorroïde sortie." },
  { ar: "مُرْضِعَة", translit: "mourdiʿa", def: "Femme qui allaite un enfant." },
  { ar: "ظِئْر", translit: "zi'r", def: "Nourrice qui allaite l'enfant d'une autre, souvent contre salaire." },
  { ar: "جَزَّار", translit: "jazzâr", def: "Boucher." },
  { ar: "دِرْهَم", translit: "dirham", def: "Pièce d'argent ; ici, mesure de surface d'une tache (le dirham « baghlī »)." },
  { ar: "الدِّرْهَمُ البَغْلِيّ", translit: "ad-dirhamou l-baghliyy", def: "Le rond qu'on voit à l'intérieur de l'avant-bras du mulet ; selon Ibn Farḥūn, une ancienne monnaie dite « tête de mulet »." },
  { ar: "خِنْصَر", translit: "khinsar", def: "Petit doigt ; sa dernière phalange sert, selon un avis, de mesure du peu de sang." },
  { ar: "رُءُوسُ الإِبَرِ", translit: "rou'oûsou l-ibar", def: "« Têtes d'aiguilles » : très fines éclaboussures (d'urine)." },
  { ar: "غَازٍ", translit: "ghâzin", def: "Combattant parti en expédition contre l'ennemi." },
  { ar: "أَرْضُ الحَرْبِ", translit: "ardou l-harb", def: "Territoire ennemi, en guerre avec les musulmans." },
  { ar: "بَعُوض", translit: "baʿoûd", def: "Moustiques ; leur trace est tolérée comme celle de la mouche." },
  { ar: "بَنَاتُ وَرْدَانَ", translit: "banâtou wardâna", def: "Blattes ; selon al-Ḥaṭṭāb, on peut s'en garder : leur trace n'est pas tolérée." },
  { ar: "حِجَامَة", translit: "hijâma", def: "Pose de ventouses avec incisions, pour tirer du sang." },
  { ar: "شَرَطَات", translit: "charatât", def: "Incisions faites sur la peau lors de la pose des ventouses." },
  { ar: "مَسْح", translit: "mas-h", def: "Essuyage : passer la main ou un linge sur un endroit sans le laver." },
  { ar: "إِطْلَاق", translit: "itlâq", def: "Sens absolu, sans distinction ; ici, reprise dans le temps pour l'oubli comme pour l'omission volontaire." },
  { ar: "طِينُ المَطَرِ", translit: "tînou l-matar", def: "Boue de pluie : boue des rues et des chemins mouillés par la pluie." },
  { ar: "مُسْتَنْقِع", translit: "moustanqiʿ", def: "Eau qui stagne dans les rues ; ʿIyāḍ le lit avec kasra sur le qāf (al-Dardīr imprime مُسْتَنْقَع)." },
  { ar: "مَاءُ الرَّشِّ", translit: "mâ'ou r-rachch", def: "Eau dont on arrose les rues ; tolérée toujours." },
  { ar: "مُحَصَّب", translit: "mouhassab", def: "Couvert de gravier (sol d'une mosquée)." },
  { ar: "عَيْنُ النَّجَاسَةِ", translit: "ʿaynou n-najâsa", def: "La substance même de l'impureté, distincte de ce à quoi elle est mêlée." }
]);
